-- Purpose: load core star schema from staging
-- Order matters: dimensions first, facts last (foreign keys)
-- Safe to re-run: ON CONFLICT DO NOTHING skips existing rows

BEGIN;
-- 1. Services: fixed keys (1 = Spotify, 2 = YouTube Music)
INSERT INTO core.dim_service (service_key, service_name)
VALUES (1, 'Spotify'),
       (2, 'YouTube Music')
ON CONFLICT (service_key) DO NOTHING;

-- 2. Devices: keys generated by IDENTITY
INSERT INTO core.dim_device (device_name)
VALUES ('Android'), ('Windows'), ('Web Player'), ('Unknown')
ON CONFLICT (device_name) DO NOTHING;

-- 3. Hours 0-23 with part of day
INSERT INTO core.dim_time (hour_key, part_of_day)
SELECT h,
        CASE
            WHEN h < 6 THEN 'night'
            WHEN h < 12 THEN 'morning'
            WHEN h < 18 THEN 'afternoon'
            ELSE 'evening'
        END
FROM generate_series(0, 23) AS h
ON CONFLICT (hour_key) DO NOTHING;

-- 4. Calendar: one row per day from first to last play (Kyiv time)
WITH bounds AS (
    SELECT MIN(d) AS d_min,
           MAX(d) AS d_max
    FROM (
        SELECT (played_at_utc AT TIME ZONE 'Europe/Kyiv')::date AS d
        FROM staging.stg_spotify_streams
        UNION ALL
        SELECT (played_at_utc AT TIME ZONE 'Europe/Kyiv')::date
        FROM staging.stg_ytm_history
    ) AS x
)
INSERT INTO core.dim_date (date_key, full_date, year, quarter, month, month_name,
                           iso_week, day_of_week, day_name, is_weekend)
SELECT to_char(dd.d, 'YYYYMMDD')::int,
       dd.d,
       EXTRACT(YEAR    FROM dd.d),
       EXTRACT(QUARTER FROM dd.d),
       EXTRACT(MONTH   FROM dd.d),
       trim(to_char(dd.d, 'Month')),
       EXTRACT(WEEK    FROM dd.d),
       EXTRACT(ISODOW  FROM dd.d),
       trim(to_char(dd.d, 'Day')),
       EXTRACT(ISODOW  FROM dd.d) IN (6, 7)
FROM bounds,
     generate_series(bounds.d_min, bounds.d_max, INTERVAL '1 day') AS g(day_ts),
     LATERAL (SELECT g.day_ts::date AS d) AS dd
ON CONFLICT (date_key) DO NOTHING;

-- 5. Artists from both platforms; display name = most frequent spelling
WITH all_artists AS (
    SELECT artist_name FROM staging.stg_spotify_streams
    UNION ALL
    SELECT artist_name FROM staging.stg_ytm_history
),
ranked AS (
    SELECT trim(artist_name)                AS artist_name,
           core.normalize_name(artist_name) AS artist_name_normalized,
           COUNT(*)                         AS plays
    FROM all_artists
    WHERE artist_name IS NOT NULL
      AND trim(artist_name) <> ''
    GROUP BY 1, 2
)
INSERT INTO core.dim_artist (artist_name, artist_name_normalized)
SELECT DISTINCT ON (artist_name_normalized)
       artist_name,
       artist_name_normalized
FROM ranked
ORDER BY artist_name_normalized, plays DESC
ON CONFLICT (artist_name_normalized) DO NOTHING;

-- 6. Tracks: one per (artist, normalized track name); album from Spotify when known
WITH all_tracks AS (
    SELECT artist_name, track_name, album_name FROM staging.stg_spotify_streams
    UNION ALL
    SELECT artist_name, track_name, NULL       FROM staging.stg_ytm_history
),
ranked AS (
    SELECT core.normalize_name(artist_name) AS artist_norm,
           core.normalize_name(track_name)  AS track_norm,
           trim(track_name)                 AS track_name,
           album_name,
           COUNT(*)                         AS plays
    FROM all_tracks
    WHERE artist_name IS NOT NULL AND trim(artist_name) <> ''
      AND track_name  IS NOT NULL AND trim(track_name)  <> ''
    GROUP BY 1, 2, 3, 4
)
INSERT INTO core.dim_track (artist_key, track_name, track_name_normalized, album_name)
SELECT DISTINCT ON (a.artist_key, r.track_norm)
       a.artist_key,
       r.track_name,
       r.track_norm,
       COALESCE(r.album_name, 'Unknown')
FROM ranked AS r
JOIN core.dim_artist AS a
  ON a.artist_name_normalized = r.artist_norm
ORDER BY a.artist_key, r.track_norm, (r.album_name IS NULL), r.plays DESC
ON CONFLICT (artist_key, track_name_normalized) DO NOTHING;

-- 7. Facts: Spotify (full set of metrics)
INSERT INTO core.fact_streams (service_key, track_key, artist_key, device_key, date_key, hour_key,
                               played_at_utc, ms_played, is_skipped, is_shuffle,
                               reason_start, reason_end, source_item_id)
SELECT 1,
       t.track_key,
       a.artist_key,
       d.device_key,
       to_char(s.played_at_utc AT TIME ZONE 'Europe/Kyiv', 'YYYYMMDD')::int,
       EXTRACT(HOUR FROM s.played_at_utc AT TIME ZONE 'Europe/Kyiv'),
       s.played_at_utc,
       s.ms_played,
       s.is_skipped,
       s.is_shuffle,
       s.reason_start,
       s.reason_end,
       COALESCE(s.spotify_track_uri, 'no_uri')
FROM staging.stg_spotify_streams AS s
JOIN core.dim_artist AS a
  ON a.artist_name_normalized = core.normalize_name(s.artist_name)
JOIN core.dim_track AS t
  ON t.artist_key = a.artist_key
 AND t.track_name_normalized = core.normalize_name(s.track_name)
JOIN core.dim_device AS d
  ON d.device_name = COALESCE(s.device_name, 'Unknown')
ON CONFLICT ON CONSTRAINT uq_fact_stream DO NOTHING;

-- 8. Facts: YouTube Music (no duration, skips or device in the export -> NULL / Unknown)
INSERT INTO core.fact_streams (service_key, track_key, artist_key, device_key, date_key, hour_key,
                               played_at_utc, source_item_id)
SELECT 2,
       t.track_key,
       a.artist_key,
       (SELECT device_key FROM core.dim_device WHERE device_name = 'Unknown'),
       to_char(y.played_at_utc AT TIME ZONE 'Europe/Kyiv', 'YYYYMMDD')::int,
       EXTRACT(HOUR FROM y.played_at_utc AT TIME ZONE 'Europe/Kyiv'),
       y.played_at_utc,
       COALESCE(y.video_id, 'no_id')
FROM staging.stg_ytm_history AS y
JOIN core.dim_artist AS a
  ON a.artist_name_normalized = core.normalize_name(y.artist_name)
JOIN core.dim_track AS t
  ON t.artist_key = a.artist_key
 AND t.track_name_normalized = core.normalize_name(y.track_name)
ON CONFLICT ON CONSTRAINT uq_fact_stream DO NOTHING;

COMMIT;